CREATE SEQUENCE IF NOT EXISTS bms_admission_number;
CREATE TABLE bms_admission_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id), value jsonb NOT NULL, logo bytea);
INSERT INTO bms_admission_settings(value) VALUES('{"enabled":false,"years":["2026/2027","2027/2028"],"contactPhone":"024 491 9825","contactEmail":"greatsage33@gmail.com","requirements":"Prepare a passport photograph and proof of age. Previous school reports are needed for transfer applicants.","requiredDocuments":["photograph","proof_of_age"],"extraFields":[],"letterTemplate":"We are pleased to offer {student} admission to {class} for the {year} academic year. Please report on {reportingDate} and accept this offer by {deadline}. Bring the original proof of age and previous school report, where applicable, for verification.","notificationTemplate":"There is an update to application {reference}. Please sign in securely at {url} to view it.","signatory":"School Administrator","retentionDays":365,"staffPermissions":[],"logoPath":"/assets/logo.png"}');
CREATE TABLE bms_admission_classes(id uuid PRIMARY KEY, name text NOT NULL, year text NOT NULL, enabled boolean NOT NULL DEFAULT false, capacity integer NOT NULL DEFAULT 0 CHECK(capacity>=0), waitlist boolean NOT NULL DEFAULT true, opens date, closes date, UNIQUE(name,year), CHECK(closes IS NULL OR opens IS NULL OR closes>=opens));
CREATE TABLE bms_admission_otps(id uuid PRIMARY KEY, email text NOT NULL, digest text NOT NULL, expires timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0, consumed boolean NOT NULL DEFAULT false);
CREATE INDEX ON bms_admission_otps(email,expires);
CREATE TABLE bms_admission_sessions(digest text PRIMARY KEY, email text NOT NULL, expires timestamptz NOT NULL);
CREATE TABLE bms_admissions(id uuid PRIMARY KEY, email text NOT NULL, reference text UNIQUE, class_id uuid REFERENCES bms_admission_classes(id), data jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','received','review','information','interview','offered','waitlisted','unsuccessful','accepted','enrolled')), public_message text NOT NULL DEFAULT '', private_notes text NOT NULL DEFAULT '', interview_at timestamptz, reporting_date date, deadline date, student_id uuid REFERENCES bms_students(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz);
CREATE INDEX ON bms_admissions(email);
CREATE INDEX ON bms_admissions(class_id,status);
CREATE TABLE bms_admission_files(id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES bms_admissions(id) ON DELETE CASCADE, kind text NOT NULL, name text NOT NULL, mime text NOT NULL, content bytea NOT NULL, size integer NOT NULL CHECK(size>0 AND size<=3000000), UNIQUE(application_id,kind));
CREATE TABLE bms_admission_downloads(digest text PRIMARY KEY, file_id uuid NOT NULL REFERENCES bms_admission_files(id) ON DELETE CASCADE, expires timestamptz NOT NULL);
CREATE TABLE bms_admission_history(id bigserial PRIMARY KEY, application_id uuid NOT NULL REFERENCES bms_admissions(id) ON DELETE CASCADE, status text NOT NULL, message text NOT NULL DEFAULT '', actor_id uuid REFERENCES bms_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bms_admission_notifications(id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES bms_admissions(id) ON DELETE CASCADE, event_key text NOT NULL UNIQUE, email text NOT NULL, body text NOT NULL, sent_at timestamptz, attempts integer NOT NULL DEFAULT 0, next_attempt timestamptz NOT NULL DEFAULT now(), last_error text);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['bms_admission_settings','bms_admission_classes','bms_admission_otps','bms_admission_sessions','bms_admissions','bms_admission_files','bms_admission_downloads','bms_admission_history','bms_admission_notifications'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t); END LOOP; END $$;
-- No public policies: all access is authorised by the server, using the private database role.
INSERT INTO bms_admission_classes(id,name,year)
SELECT md5('admissions-2026-'||name)::uuid,name,'2026/2027' FROM unnest(ARRAY['Crèche','Nursery 1','Nursery 2','Kindergarten 1','Kindergarten 2','Basic 1','Basic 2','Basic 3','Basic 4','Basic 5','Basic 6','Basic 7','Basic 8','Basic 9']) AS name;
